export function getTranslation(lang: string, key: string, params?: Record<string, string | number>): string {
  const dict = (translations as any)[lang] || translations.en
  let text = dict[key] || translations.en[key as keyof typeof translations.en] || key
  if (params) {
    for (const [k, v] of Object.entries(params)) {
      text = text.replace(new RegExp(`\\{${k}\\}`, 'g'), String(v))
    }
  }
  return text
}
